        "법령⚖️": "Laws⚖️",
        "판례📜": "Precedents📜",
        "legalize-kr 저장소": "legalize-kr repository",
        "precedent-kr 저장소": "precedent-kr repository",
        "ordinance-kr 저장소": "ordinance-kr repository",
        "admrule-kr 저장소": "admrule-kr repository",
        "로 법령의": " to view a law's",
        "로": " with",
        "로 판례가": " to see precedents'",
